-- 064_exercise_content.sql
-- The library's French and German names, descriptions and demo videos move
-- from lists in the app's code to the exercises themselves (name_fr,
-- name_de, description_fr, description_de, video_url), where an admin edits
-- them (Exercises, Edit). Only empty fields are filled: an admin's changes
-- are kept.
--
-- Deploy: apply this file BEFORE the code: the app no longer carries these
-- lists, and shows English names until the devices have synced again (done
-- on its own once online).
--
-- Safe to re-run: filled only where empty.

BEGIN;

UPDATE exercises SET name_fr = COALESCE(name_fr, 'Arabesque (équilibre)'), name_de = COALESCE(name_de, 'Standwaage'), description_fr = COALESCE(description_fr, 'Sur une jambe, pencher le buste et monter l’autre jambe derrière à hauteur de hanche, bras ouverts. Tenir, dos long.'), description_de = COALESCE(description_de, 'Auf einem Bein den Oberkörper neigen und das andere Bein hinten auf Hüfthöhe heben, Arme seitlich. Halten, Rücken lang.'), video_url = COALESCE(video_url, 'https://www.youtube.com/watch?v=YoJ9ycg8Txs'), updated_at = now() WHERE user_id IS NULL AND name = 'Arabesque Hold' AND (name_fr IS NULL OR name_de IS NULL OR description_fr IS NULL OR description_de IS NULL OR video_url IS NULL);
